{\itshape
As representations of $\textnormal{\textbf{Vir}}\oplus\overline\textnormal{\textbf{Vir}}$, we have the isomorphism
\begin{align*}
\bigg\{
    \begin{array}{c}
    \text{local observables of} \\
    \text{the fermionic DGFF}
    \end{array}
\bigg\}
\; \cong \;
\bigg\{
    \begin{array}{c}
    \text{local fields of the} \\
    \text{symplectic fermions}
    \end{array}
\bigg\}\,.
\end{align*}
}

{\itshape
Let $\boldsymbol{\varphi}_1 , \ldots , \boldsymbol{\varphi}_n$ be symplectic-fermions local fields with generalised scaling \linebreak[3] dimensions $D_1 , \ldots , D_n$ respectively.
Let $F_i$ and $\tilde{F}_i$ be the fDGFF local observables corres\-ponding ---via Theorem~1--- to the local field $\boldsymbol{\varphi}_i$ and $[(\textnormal{L}_{0}+ 
    \mathrlap{\hspace{-1pt}\overline{\scalebox{0.85}[1]{\phantom{\ensuremath{\textnormal{L}}}}}}\ensuremath{\textnormal{L}}
_{0})-D_i]\boldsymbol{\varphi}_i$, respectively.
Then, we have
\begin{align*}
    \frac{
    \Big\langle
    \Big(
    F_1(z^\delta_1) - \log ( \lambda \delta ) \tilde{F}_1(z^\delta_1)
    \Big)
    \!\cdots\!
    \Big(
    F_n(z^\delta_n) - \log ( \lambda \delta ) \tilde{F}_n(z^\delta_n)
    \Big)
    \Big\rangle^{\textnormal{fDGFF}}_{\Omega^{\delta}}
    \!\!\!\!\!\!\!\!
    }{
    \mathlarger{\mathlarger{\delta}}^{\,D_1}
    \;\cdots\;
    \mathlarger{\mathlarger{\delta}}^{\,D_n}
    }
    \mspace{4mu}
    \xrightarrow{\mspace{20mu} \delta \downarrow 0 \mspace{20mu}}
    \mspace{1mu}
    \Big\langle
    \boldsymbol{\varphi}_1(z_1) \cdots \boldsymbol{\varphi}_n(z_n)
    \Big\rangle^{\textnormal{SyFe}}_{\Omega;\lambda}
\end{align*}
uniformly for $z_1, \ldots , z_n$ on compacts of $\Omega$ and away from one another.
}

\label{lemma: sugawara}
The linear operators on $\mathscr{F}{\!\!\textnormal{\footnotesize\itshape ock}}$ given by the formal sums
\begin{align*}
{\mathsf{L}}_{n}
\coloneqq
\sum_{k \,\geq\, n/2}
{\upchi}_{n-k}{\upeta}_{k}
-
\sum_{k \,<\, n/2}
{\upeta}_{k}{\upchi}_{n-k}
\mspace{30mu}
\text{ and }
\mspace{30mu}

    \mathrlap{\hspace{-0.3pt}\overline{\scalebox{0.6}[1]{\phantom{\ensuremath{\mathsf{L}}}}}}\ensuremath{\mathsf{L}}
_{n}
\coloneqq
\sum_{k \,\geq\, n/2}

    \mathrlap{\hspace{-0.6pt}\overline{\scalebox{1}[1]{\phantom{\ensuremath{\upchi}}}}}\ensuremath{\upchi}
_{n-k} 
    \mathrlap{\hspace{-0.6pt}\overline{\scalebox{0.97}[1]{\phantom{\ensuremath{\upeta}}}}}\ensuremath{\upeta}
_{k}
-
\sum_{k \,<\, n/2}

    \mathrlap{\hspace{-0.6pt}\overline{\scalebox{0.97}[1]{\phantom{\ensuremath{\upeta}}}}}\ensuremath{\upeta}
_{k} 
    \mathrlap{\hspace{-0.6pt}\overline{\scalebox{1}[1]{\phantom{\ensuremath{\upchi}}}}}\ensuremath{\upchi}
_{n-k}\,,
\end{align*}
for $n\in{\mathbb Z}$, are well-defined and constitute two commuting representations of the Virasoro algebra with central charge $-2$.
That is, they satisfy
\begin{align*}
    & \,
    \big[ \,{\mathsf{L}}_{n}, {\mathsf{L}}_{m} \big]
    \,=\,
    (n-m) \, {\mathsf{L}}_{n+m} +  \frac{c}{12} \,(n^3-n) \, \delta_{n+m}  \, \textnormal{id}_{\mathscr{F}{\!\!\textnormal{\footnotesize\itshape ock}}}\,,
    \\
    \phantom{\Bigg\vert}
    & \,
    \big[ \, 
    \mathrlap{\hspace{-0.3pt}\overline{\scalebox{0.6}[1]{\phantom{\ensuremath{\mathsf{L}}}}}}\ensuremath{\mathsf{L}}
_{n},  
    \mathrlap{\hspace{-0.3pt}\overline{\scalebox{0.6}[1]{\phantom{\ensuremath{\mathsf{L}}}}}}\ensuremath{\mathsf{L}}
_{m} \big]
    \,=\,
    (n-m) \,  
    \mathrlap{\hspace{-0.3pt}\overline{\scalebox{0.6}[1]{\phantom{\ensuremath{\mathsf{L}}}}}}\ensuremath{\mathsf{L}}
_{n+m} +  \frac{c}{12} \,(n^3-n) \, \delta_{n+m}  \, \textnormal{id}_{\mathscr{F}{\!\!\textnormal{\footnotesize\itshape ock}}}\,,
    \mspace{20mu} \text{and}
    \\
    & \,
    \big[ \,{\mathsf{L}}_{n},  
    \mathrlap{\hspace{-0.3pt}\overline{\scalebox{0.6}[1]{\phantom{\ensuremath{\mathsf{L}}}}}}\ensuremath{\mathsf{L}}
_{m} \big]
    \,=\,
    0
\end{align*}
with $c=-2$.

\label{thm: characterization of CF}
For each complex number $\alpha\in{\mathbb C}$, there exists a unique collection
of correlation functions with the following properties:
\begin{description}[style=sameline]


	\item[(FER)]
	The correlation functions of the ground fermions are
	\begin{align*}
		\Big\langle \boldsymbol{\xi}(z_1)\,\boldsymbol{\theta}(w_1)\cdots\boldsymbol{\xi}(z_n)\,\boldsymbol{\theta}(w_n) \Big\rangle_{\Omega; \alpha}^{\textnormal{SyFe}}
		\, = \,
		(4\pi)^n
		\displaystyle\sum_{\sigma\in\mathcal{S}_n} \textnormal{sgn}(\sigma)
		\displaystyle\prod_{i=1}^n
		\mathbf{G}_\Omega\big(z_i,w_{\sigma(i)}\big)
	\end{align*}
	for $(z_1,\ldots,z_n,w_1\ldots,w_n)\in\textnormal{Conf}_{2n}( \Omega )$,
	they vanish when the number of
	\linebreak[4]
	$\boldsymbol{\xi}$-inser\-tions and $\boldsymbol{\theta}$-insertions do not coincide,
	and they satisfy
	\begin{align*}
		\Big\langle \cdots\boldsymbol{\xi}(z)\,\boldsymbol{\theta}(w)\cdots \Big\rangle_{\Omega; \alpha}^{\textnormal{SyFe}}
		\,=
		-\,\Big\langle \cdots\boldsymbol{\theta}(w)\,\boldsymbol{\xi}(z)\cdots \Big\rangle_{\Omega; \alpha}^{\textnormal{SyFe}}\,.
	\end{align*}



	\item[(DER)]
	For the Virasoro modes~${\mathsf{L}}_{-1}$ and $ 
    \mathrlap{\hspace{-0.3pt}\overline{\scalebox{0.6}[1]{\phantom{\ensuremath{\mathsf{L}}}}}}\ensuremath{\mathsf{L}}
_{-1}$ we have
	\begin{align*}
		\Big\langle \big[{\mathsf{L}}_{-1}\boldsymbol{\varphi}\big](z)\cdots \Big\rangle_{\Omega; \alpha}^{\textnormal{SyFe}}
		\  = \ 
		\partial_z\,\Big\langle \boldsymbol{\varphi}(z)\cdots \Big\rangle_{\Omega; \alpha}^{\textnormal{SyFe}}	
	\end{align*}
	and
	\begin{align*}
		\;\Big\langle \big[\mspace{1mu} 
    \mathrlap{\hspace{-0.3pt}\overline{\scalebox{0.6}[1]{\phantom{\ensuremath{\mathsf{L}}}}}}\ensuremath{\mathsf{L}}
_{-1}\boldsymbol{\varphi}\big](z)\cdots \Big\rangle_{\Omega; \alpha}^{\textnormal{SyFe}}
		\  = \ 

    \mathrlap{\hspace{1pt}\overline{\scalebox{0.8}[1]{\phantom{\ensuremath{\partial}}}}}\ensuremath{\partial}
_z\,\Big\langle \boldsymbol{\varphi}(z)\cdots \Big\rangle_{\Omega; \alpha}^{\textnormal{SyFe}}\,,
	\end{align*}
	for any field~$\boldsymbol{\varphi}\in\mathscr{F}{\!\!\textnormal{\footnotesize\itshape ock}}$.


\item[(CUR)]                       
Within correlation functions, we have
\begin{align*}

    \boldsymbol{\chi}(z)\boldsymbol{\varphi}(w)
    \,=\,
    \sum_{k\in{\mathbb Z}}\,
    \frac{\,\big[{\upchi}_{k}\boldsymbol{\varphi}\big](w)\,}{\,(z-w)^{k+1}}\,,
    \mspace{20mu}
    &
    \mspace{59mu}
    \overline{\boldsymbol{\chi}}(z)\boldsymbol{\varphi}(w)
    \,=\,
    \sum_{k\in{\mathbb Z}}\,
    \frac{\,\big[ 
    \mathrlap{\hspace{-0.6pt}\overline{\scalebox{1}[1]{\phantom{\ensuremath{\upchi}}}}}\ensuremath{\upchi}
_{k}\boldsymbol{\varphi}\big](w)\,}{\,(\overline{z}-\overline{w})^{k+1}}\,,
    \\
    \phantom{.}
    \\
    \boldsymbol{\eta}(z)\boldsymbol{\varphi}(w)
    \,=\,
    \sum_{k\in{\mathbb Z}}\,
    \frac{\,\big[{\upeta}_{k}\boldsymbol{\varphi}\big](w)\,}{\,(z-w)^{k+1}}\,,
    \mspace{20mu}
    &
    \text{ and }
    \mspace{20mu}
    \overline{\boldsymbol{\eta}}(z)\boldsymbol{\varphi}(w)
    \,=\,
    \sum_{k\in{\mathbb Z}}\,
    \frac{\,\big[ 
    \mathrlap{\hspace{-0.6pt}\overline{\scalebox{0.97}[1]{\phantom{\ensuremath{\upeta}}}}}\ensuremath{\upeta}
_{k}\boldsymbol{\varphi}\big](w)\,}{\,(\overline{z}-\overline{w})^{k+1}}
\end{align*}
for any field $\boldsymbol{\varphi}\in\mathscr{F}{\!\!\textnormal{\footnotesize\itshape ock}}$ for small enough $\vert z - w \vert$.

\item[(LOG)]
We have
\begin{align*}
    \Big\langle  \boldsymbol{\xi}(z)\boldsymbol{\theta}(w) \cdots  \Big\rangle_{\Omega; \alpha}^{\textnormal{SyFe}}
    \,=\, &\,
    \log \frac{1}{\vert z-w\vert^2}
    \Big\langle  \boldsymbol{\mathbbm{1}}(w) \cdots  \Big\rangle_{\Omega; \alpha}^{\textnormal{SyFe}}
    \,-\,
    \Big\langle  \big[\boldsymbol{\omega} + \alpha \, \boldsymbol{\mathbbm{1}}\big](w) \cdots  \Big\rangle_{\Omega; \alpha}^{\textnormal{SyFe}}
    \\
    &\,
    \,+\, 
    o\big(\vert z - w\vert\big) \phantom{\Bigg\vert}
    \,
\end{align*}
as $\vert z - w \vert \to 0$.
\end{description}

\label{rmk: integral formula}
Consider, for $i=1,\ldots,n$, the $\mathscr{F}{\!\!\textnormal{\footnotesize\itshape ock}}$ elements
\begin{align*}
\boldsymbol{\varphi}_i
\,\coloneqq\,
{\upchi}_{-k_{\alpha_i}^{(i)}}\cdots{\upchi}_{-k_1^{(i)}}
{\upeta}_{-\ell_{\beta_i}^{(i)}}\cdots{\upeta}_{-\ell_1^{(i)}}

    \mathrlap{\hspace{-0.6pt}\overline{\scalebox{1}[1]{\phantom{\ensuremath{\upchi}}}}}\ensuremath{\upchi}
_{-\bar{k}_{\bar\alpha_i}^{(i)}}\cdots 
    \mathrlap{\hspace{-0.6pt}\overline{\scalebox{1}[1]{\phantom{\ensuremath{\upchi}}}}}\ensuremath{\upchi}
_{-\bar{k}_1^{(i)}}

    \mathrlap{\hspace{-0.6pt}\overline{\scalebox{0.97}[1]{\phantom{\ensuremath{\upeta}}}}}\ensuremath{\upeta}
_{-\bar\ell_{\bar\beta_i}^{(i)}}\cdots 
    \mathrlap{\hspace{-0.6pt}\overline{\scalebox{0.97}[1]{\phantom{\ensuremath{\upeta}}}}}\ensuremath{\upeta}
_{-\bar\ell_1^{(i)}}
\boldsymbol{\omega}
\in \mathscr{F}{\!\!\textnormal{\footnotesize\itshape ock}}\,,
\end{align*}
in the basis~\eqref{eq: fock basis}.
By property \textbf{(CUR)}, their correlation functions can be obtained as
\begin{align*}
    &
    \Big\langle 
    \boldsymbol{\varphi}_1(z_1)
    \,\cdots\,
    \boldsymbol{\varphi}_n(z_n)
     \Big\rangle_{\Omega; \alpha}^{\textnormal{SyFe}}
    \,=\,
    \oint \!\cdots\! \oint
    \prod_{i=1}^n
    \Bigg(
    \prod_{a=1}^{\alpha_i}
    \frac{\textnormal{d} \zeta_{i;a}^{\chi}}{2\pi\mathbbm{i}}
    \prod_{b=1}^{\beta_i}
    \frac{\textnormal{d} \zeta_{i;b}^{\eta}}{2\pi\mathbbm{i}}
    \prod_{\bar a=1}^{\bar\alpha_i}
    \frac{\textnormal{d} \overline{\zeta}_{i;\bar a}^{\bar \chi}}{\overline{2\pi\mathbbm{i}}}
    \prod_{\bar b=1}^{\bar\beta_i}
    \frac{\textnormal{d} \overline{\zeta}_{i;\bar b}^{\bar \eta}}{\overline{2\pi\mathbbm{i}}}
    \Bigg)
    \times
    \\
    &
    \mspace{60mu}
    \times
    \prod_{i=1}^n
    \Bigg(
    \prod_{a=1}^{\alpha_i}
    \, \big( \zeta_{i;a}^{\chi} - z_i \big)^{-k_a^{(i)}}
    \prod_{b=1}^{\beta_i}
    \, \big( \zeta_{i;b}^{\eta} - z_i \big)^{-\ell_b^{(i)}}
    \prod_{\bar a=1}^{\bar\alpha_i}
    \, \Big( \overline{ \zeta_{i;\bar a}^{\bar \chi} - z_i}\Big)^{-\bar{k}_{\bar a}^{(i)}}
    \prod_{\bar b=1}^{\bar\beta_i}
    \, \Big(\overline{\zeta_{i;\bar b}^{\bar\eta} - z_i}\Big)^{-\bar{\ell}_{\bar b}^{(i)}}
    \Bigg)
    \times
    \\
    &
    \times\!
    \bigg\langle
    \boldsymbol{\chi}\big( \zeta_{1;1}^{\chi} \big) \cdots \boldsymbol{\chi}\big( \zeta_{1;\alpha_1}^{\chi} \big)
    \boldsymbol{\eta}\big( \zeta_{1;1}^{\eta} \big) \cdots \boldsymbol{\eta}\big( \zeta_{1;\beta_1}^{\eta} \big)
    \overline{\boldsymbol{\chi}}\big( \zeta_{1;1}^{\bar \chi} \big) 
    \cdots
    \overline{\boldsymbol{\chi}}\big( \zeta_{1;\bar\alpha_1}^{\bar \chi} \big)
    \overline{\boldsymbol{\eta}}\big( \zeta_{1;1}^{\bar \eta} \big)
    \cdots
    \overline{\boldsymbol{\eta}}\big( \zeta_{1;\bar\beta_1}^{\bar \eta} \big)\,
    \boldsymbol{\omega}(z_1)
    \cdots\phantom{\Bigg\vert}
    \\
    &
    \mspace{10mu}
    \cdots
    \boldsymbol{\chi}\big( \zeta_{n;1}^{\chi} \big) \cdots \boldsymbol{\chi}\big( \zeta_{n;\alpha_n}^{\chi} \big)
    \boldsymbol{\eta}\big( \zeta_{n;1}^{\eta} \big) \cdots \boldsymbol{\eta}\big( \zeta_{n;\beta_n}^{\eta} \big)
    \overline{\boldsymbol{\chi}}\big( \zeta_{n;1}^{\bar \chi} \big) 
    \cdots
    \overline{\boldsymbol{\chi}}\big( \zeta_{n;\bar\alpha_n}^{\bar \chi} \big)
    \overline{\boldsymbol{\eta}}\big( \zeta_{n;1}^{\bar \eta} \big)
    \cdots
    \overline{\boldsymbol{\eta}}\big( \zeta_{n;\bar\beta_n}^{\bar \eta} \big)\,
    \boldsymbol{\omega}(z_n)
    \bigg\rangle_{\Omega;\alpha}^{\textnormal{SyFe}}
\end{align*}
where the integrals are performed along non-intersecting contours in the following way:
for each $i = 1 , \ldots , n$, the variables $\zeta_{i;a}^{\chi}$, $\zeta_{i;b}^{\eta}$, $\zeta_{i;\bar a}^{\bar \chi}$ and $\zeta_{i;\bar b}^{\bar \eta}$ are integrated along nested contours around the point $z_i$ in the radial order
\begin{align*}
    \zeta_{i;1}^{\chi} , \ldots , \zeta_{i;\alpha_i}^{\chi},
    \zeta_{i;1}^{\eta} , \ldots , \zeta_{i;\beta_i}^{\eta},
    \zeta_{i;1}^{\bar \chi} , \ldots , \zeta_{i;\bar\alpha_i}^{\bar \chi},
    \zeta_{i;1}^{\bar \eta} , \ldots , \zeta_{i;\bar\beta_i}^{\bar \eta}
\end{align*}
in the inward direction.
\hfill$\diamond$

\label{ex: 1pt fctn log partner}
We have
\begin{align*}
    \Big\langle \boldsymbol{\omega}(z) \Big\rangle_{\Omega; \alpha}^{\textnormal{SyFe}}
    \,=\,
    - \, 4\pi\,\mathbf{g}_{\Omega}(z,z) - \alpha \,,
\end{align*}
where $\mathbf{g}_\Omega$ is the harmonic part of the Green's function~$\mathbf{G}_\Omega$.
Note that this one-point function is related to the conformal radius~$\mathrm{R}(z;\Omega)$ of the domain~$\Omega$ from the point~$z\in\Omega$ since we have $\mathrm{R}(z;\Omega) = \exp\big(2\pi\mathbf{g}_\Omega(z,z)\big)$.
\hfill$\diamond$

\label{rmk: general wick formula}
The correlation functions of the ground states $\boldsymbol{\xi}$, $\boldsymbol{\theta}$, and $\boldsymbol{\omega}$ satisfy the following formula:
Take three non-intersecting collections $\underline{z}  \coloneqq\{z_1,\ldots,z_n\}$, $\underline{w}  \coloneqq\{w_1,\ldots,w_n\}$ and $\underline{x}  \coloneqq\{x_1,\ldots,x_k\}$ of distinct points in the domain~$\Omega$.
Let ${\mathfrak{B}(\underline{ z}  ,\underline{ w}  ;\underline{ x}  )}$ denote the set of bi\-jec\-tions from the set~${\underline{ z}  \cup\underline{ x}  }$ onto the set~${\underline{w}  \cup\underline{ x}  }$.
We have
\begin{align*}
    \Big\langle \boldsymbol{\xi}(z_1)\boldsymbol{\theta}(w_1)&\cdots\boldsymbol{\xi}(z_n)\boldsymbol{\theta}(w_n)
    \boldsymbol{\omega}(x_k)\cdots\boldsymbol{\omega}(x_1) \Big\rangle_{\Omega; \alpha}^{\textnormal{SyFe}}
    \\
    & = \phantom{\bigg\vert}
    (-1)^k\sum_{b\in\mathfrak{B}(\underline{z}  ,\underline{w}  ;\underline{x}  )}
    (-1)^b(-1)^{F_b}
    \prod_{\underset{b(y)\neq y}{y\in\underline{z}  \cup\underline{x}  }}
    \Big\langle \boldsymbol{\xi}(y)\boldsymbol{\theta}\big(b(y)\big) \Big\rangle_{\Omega; \alpha}^{\textnormal{SyFe}}
    \prod_{\underset{b(x)= x}{x\in\underline{x}  }}
    \Big\langle \boldsymbol{\omega}(x) \Big\rangle_{\Omega; \alpha}^{\textnormal{SyFe}}\,,
\end{align*}
where $(-1)^b$ is the signature of the bijection $b$, and $F_b$ is the number of fixed points of $b$.
\hfill$\diamond$

\label{rmk: factorisation laplacian}
The discrete Laplacian admits the following factorisations in terms of discrete differential operators:
\begin{align*}
       \partial_\sharp 
    \mathrlap{\hspace{1pt}\overline{\scalebox{0.8}[1]{\phantom{\ensuremath{\partial}}}}}\ensuremath{\partial}
_\sharp \,=\,   
    \mathrlap{\hspace{1pt}\overline{\scalebox{0.8}[1]{\phantom{\ensuremath{\partial}}}}}\ensuremath{\partial}
_\sharp\partial_\sharp \,=\, \frac{1}{4}\,\Delta_\sharp \,,
\end{align*}
and, for a function~$f \colon {\mathbb Z}^2_\diamond\to{\mathbb C}$,
\begin{align*}
    \partial_\sharp 
    \mathrlap{\hspace{1pt}\overline{\scalebox{0.8}[1]{\phantom{\ensuremath{\partial}}}}}\ensuremath{\partial}
^\bullet_\sharp f(\mathbf{z}) \,=\,   
    \mathrlap{\hspace{1pt}\overline{\scalebox{0.8}[1]{\phantom{\ensuremath{\partial}}}}}\ensuremath{\partial}
_\sharp\partial^\bullet_\sharp f(\mathbf{z}) \,=\,
    \begin{cases} 
    \mspace{10mu}\frac{1}{2}\,\Delta_\sharp f(\mathbf{z}) & \mspace{10mu} \textnormal{ if } \mathbf{z}\in{\mathbb Z}^2_\bullet\,, \textnormal{ and } \\
    & \\
    \mspace{35mu} 0 & \mspace{10mu} \textnormal{ if } \mathbf{z}\in{\mathbb Z}^2_*\,.
    \end{cases} 
\end{align*}
We will use extensively these factorisations in our computations in later sections.
\hfill$\diamond$

\label{prop: monomials}
There exists a unique family of ${\mathbb C}$-valued functions $\{\mathbf{u}\mapsto \mathbf{u}^{[n]}\}_{n\in{\mathbb Z}}$ on
${\mathbb Z}^2_\diamond\cup{\mathbb Z}^2_\textnormal{m}$ that satisfies the following properties:
\begin{enumerate}
\item For all $n\in{\mathbb Z}$, the function $\mathbf{u} \mapsto \mathbf{u}^{[n]}$ has the same square-grid symmetries
as the Laurent monomial $z \mapsto z^n$,
i.e., $(\mathbbm{i} \mathbf{u})^{[n]}=\mathbbm{i}^n \mathbf{u}^{[n]}$ and $\overline{\mathbf{u}}^{[n]} = \overline{\mathbf{u}^{[n]}}$ for all
$\mathbf{u} \in {\mathbb Z}^2_\diamond\cup{\mathbb Z}^2_\textnormal{m}$.
\item For all $\mathbf{u}\in{\mathbb Z}^2_\diamond\cup{\mathbb Z}^2_\textnormal{m}$, $\mathbf{u}^{[0]}=1$ and, for all $n\in{\mathbb Z}$, $\partial_\sharp \mathbf{u}^{[n]} = n\,\mathbf{u}^{[n-1]}$.
\item For each $\mathbf{u}\in{\mathbb Z}^2_\diamond\cup{\mathbb Z}^2_\textnormal{m}$, there exists an $N\in{\mathbb N}$ such that $\mathbf{u}^{[n]}=0$ for all $n\geq N$.
\item For $n<0$, we have $\mathbf{u}^{[n]} \to 0$ as $\vert \mathbf{u}\vert\rightarrow \infty$.
\item The first negative-power monomial has the following explicit
failure of discrete holomorphicity near the origin
\begin{align*}
    \frac{1}{2\pi} 
    \mathrlap{\hspace{1pt}\overline{\scalebox{0.8}[1]{\phantom{\ensuremath{\partial}}}}}\ensuremath{\partial}
_\sharp \mathbf{u}^{[-1]}
    =
    \frac{1}{2} \, \delta_{\mathbf{u},0}
    +
    \frac{1}{4}
    \sum_{\vert\mathbf{v}\vert = \frac{1}{2}} 
    \delta_{\mathbf{u},\mathbf{v}}
    +
    \frac{1}{8}\sum_{\vert\mathbf{v}\vert = \frac{1}{\sqrt{2}}}
    \mspace{-5mu}
    \delta_{\mathbf{u},\mathbf{v}}\,.
\end{align*}
\item \label{property: poles}
For any $n\geq 0$ and all $\mathbf{u}\in{\mathbb Z}^2_\diamond\cup{\mathbb Z}^2_\textnormal{m}$ we have $ 
    \mathrlap{\hspace{1pt}\overline{\scalebox{0.8}[1]{\phantom{\ensuremath{\partial}}}}}\ensuremath{\partial}
_\sharp \mathbf{u}^{[n]}=0$. 
For any $n<0$, we have $ 
    \mathrlap{\hspace{1pt}\overline{\scalebox{0.8}[1]{\phantom{\ensuremath{\partial}}}}}\ensuremath{\partial}
_\sharp \mathbf{u}^{[n]}=0$ except at finitely many
points~$\mathbf{u} \in {\mathbb Z}^2_\diamond\cup{\mathbb Z}^2_\textnormal{m}$.

\item For any $n,m\in{\mathbb Z}$, we have the discrete residue formula
\begin{align*}
    \frac{1}{2\pi\mathbbm{i}}
    \sqint^{\sharp}_{\gamma} \mathbf{u}^{[n]}_\diamond \, \mathbf{u}^{[m]}_\textnormal{m} \, \textnormal{d}^{\sharp} \mathbf{u} 
    \; = \; \delta_{n+m+1}\,,
\end{align*}
for any large enough positively-oriented corner contour $\gamma$ that encircles the origin.
\item For any $n \in {\mathbb Z}$, as~${|\mathbf{u}| \to \infty}$, the discrete monomial has the asymptotics
\begin{align*}
\mathbf{u}^{[n]} = \mathbf{u}^n + o(|\mathbf{u}|^n) \,,
\end{align*}
where in $\mathbf{u}^n$ we interpret $\mathbf{u}\in{\mathbb C}$ via the embedding  ${\mathbb Z}^2 \subset {\mathbb C}$.
\end{enumerate}

\label{rmk: 2n pt function fDGFF}
The correlation function of the monomial~$\xi(\mathbf{z}_1)\cdots\xi(\mathbf{z}_n)\theta(\mathbf{w}_1)\cdots\theta(\mathbf{w}_m)$ vani\-shes unless $n=m$.
For the two-point function, we have
\begin{align*}
    \Big\langle \xi(\mathbf{z})\theta(\mathbf{w}) \Big\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}}
    \;=\;
    4\pi\,
    \mathbf{G}_{\Omega^{\delta}}(\mathbf{z},\mathbf{w})\,,
\end{align*}
where $\mathbf{G}_{\Omega^{\delta}}$ is ---up to a negative sign--- the inverse of the Dirichlet Laplacian, that is, it satisfies
\begin{align*}
    \big(\Delta_{\Omega^{\delta}}^{\texttt{D}}\big)_{(1)}
    \mathbf{G}_{\Omega^{\delta}} (\mathbf{z},\mathbf{w})
    \,=\,
    -\delta_{\mathbf{z},\mathbf{w}}
\end{align*}
for $\mathbf{z},\mathbf{w}\in\textnormal{int}\,{\Omega^{\delta}}$, where the subindex $(\,\cdot\,)_{(1)}$ indicates the Laplacian operator is taken with respect to the first variable of $\mathbf{G}_{\Omega^{\delta}}$.
Finally, the $2n$-point functions satisfy the \textbf{fermionic Wick's formula}, i.e.~we have
\begin{align*}
    \Big\langle \xi(\mathbf{z}_1)\theta(\mathbf{w}_1)\cdots\xi(\mathbf{z}_n)\theta(\mathbf{w}_n) \Big\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}}
    \;=\;
    \sum_{\sigma\in\mathfrak{S}_n}
    (-1)^\sigma
    \prod_{i=1}^n
    \Big\langle \xi(\mathbf{z}_i)\theta(\mathbf{w}_{\sigma(i)}) \Big\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}}
\end{align*}
where $\mathfrak{S}_n$ denotes the symmetric group of order~$n$ and $(-1)^\sigma$ is the signature of the permutation~$\sigma$.
\hfill$\diamond$

\label{rmk: discrete Wick with log corrections}
In a similar fashion as in Remark~\ref{rmk: general wick formula}, for three non-intersecting collections
$\underline{\mathbf{z}} \coloneqq\{\mathbf{z}_1 ,\ldots,\mathbf{z}_n \}$,
$\underline{\mathbf{w}} \coloneqq\{\mathbf{w}_1 ,\ldots,\mathbf{w}_n \}$,
and $\underline{\mathbf{x}} \coloneqq\{\mathbf{x}_1 ,\ldots,\mathbf{x}_k \}$
of points in the discrete domain~$\Omega^{\delta}$,
the set of bijections from the set~${\underline{\mathbf{z}} \cup\underline{\mathbf{x}} }$ onto the set~${\underline{\mathbf{w}} \cup\underline{\mathbf{x}} }$ is denoted by ${\mathfrak{B}(\underline{\mathbf{z}} ,\underline{\mathbf{w}} ;\underline{\mathbf{x}} )}$.
For any fixed constant $c\in{\mathbb C}$, a straightforward manipulation of the fermionic Wick formula ---Remark~\ref{rmk: 2n pt function fDGFF}--- leads to
\begin{align*}
    &
    \Big\langle \xi(\mathbf{z}_1 ) \, \theta(\mathbf{w}_1 )
    \cdots
    \xi(\mathbf{z}_n ) \, \theta(\mathbf{w}_n ) \,
    \big( \, \xi(\mathbf{x}_1 ) \, \theta(\mathbf{x}_1 ) + c \, \big)
    \cdots
    \big( \, \xi(\mathbf{x}_k ) \, \theta(\mathbf{x}_k ) + c \, \big) \Big\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}}
    \phantom{\Bigg\vert}
    \\
    & 
    \mspace{40mu}
    \phantom{\Bigg\vert}
    =
    (-1)^k \!\!
    \sum_{b\in\mathfrak{B}(  \underline{\mathbf{z}} ,  \underline{\mathbf{w}} ;  \underline{\mathbf{x}} )} \!\!\!
    (-1)^b(-1)^{F_b}
    \prod_{\underset{b(y)\neq y}{y\in  \underline{\mathbf{z}} \cup  \underline{\mathbf{x}} }}
    \Big\langle 
    \xi(\mathbf{y} ) \, \theta\big( b(\mathbf{y} ) \big) \Big\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}}
    \prod_{\underset{b(\mathbf{x} )= \mathbf{x} }{\mathbf{x} \in\underline{\mathbf{x}} }}
    \bigg(\Big\langle 
    \xi(\mathbf{x} ) \, \theta(\mathbf{x} ) \Big\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}}
    +\, c \,
    \bigg),
\end{align*}
where $(-1)^b$ is the signature of the bijection $b$, and $F_b$ is the number of fixed points of $b$.
\hfill$\diamond$

Given a medial point $\mathbf{u}_\textnormal{m}\in{\mathbb Z}^2_\textnormal{m}$, the field polynomials
\begin{align*}
    \boldsymbol{\upchi}(\mathbf{u}_\textnormal{m})
    \,\coloneqq\,
    \partial^\bullet_\sharp \boldsymbol\upxi(\mathbf{u}_\textnormal{m})\,,
    &
    \mspace{40mu}
    \phantom{\Big\vert}
    \boldsymbol{\upeta}(\mathbf{u}_\textnormal{m})
    \,\coloneqq\,
    \partial^\bullet_\sharp \boldsymbol\uptheta(\mathbf{u}_\textnormal{m})\,,
    \mspace{50mu}
    \text{ and }
    \\

    \mathrlap{\hspace{-0.7pt}\overline{\scalebox{1.1}[1]{\phantom{\ensuremath{\boldsymbol{\upchi}}}}}}\ensuremath{\boldsymbol{\upchi}}
(\mathbf{u}_\textnormal{m})
    \,\coloneqq\,

    \mathrlap{\hspace{1pt}\overline{\scalebox{0.8}[1]{\phantom{\ensuremath{\partial}}}}}\ensuremath{\partial}
^\bullet_\sharp \boldsymbol\upxi(\mathbf{u}_\textnormal{m})\,,
    &
    \mspace{40mu}
    \phantom{\Big\vert}

    \mathrlap{\hspace{-0.2pt}\overline{\scalebox{0.9}[1]{\phantom{\ensuremath{\boldsymbol{\upeta}}}}}}\ensuremath{\boldsymbol{\upeta}}
(\mathbf{u}_\textnormal{m})
    \,\coloneqq\,

    \mathrlap{\hspace{1pt}\overline{\scalebox{0.8}[1]{\phantom{\ensuremath{\partial}}}}}\ensuremath{\partial}
^\bullet_\sharp \boldsymbol\uptheta(\mathbf{u}_\textnormal{m})
\end{align*}
are called, respectively, the \textbf{holomorphic} and \textbf{antiholomorphic currrents}.
\hfill$\diamond$

\label{ex: 1 is not 0}
The field polynomial $1\in\mathcal{P}$ is not null since we have, for example,
\begin{align*}
    \Big\langle \,\textnormal{ev}^{\Omega^{\delta}}_{\mathbf{z}}(1)\,
    \xi(\mathbf{z}_1)\theta(\mathbf{w}_1) \Big\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}}
    \,=\,
    \Big\langle \,\xi(\mathbf{z}_1)\theta(\mathbf{w}_1) \Big\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}}
    \,=\,
    4\pi\,\mathbf{G}_{\Omega^{\delta}}(\mathbf{z}_1,\mathbf{w}_1)
    \,\neq\,0
\end{align*}
for any discrete domain $\Omega^{\delta}$ and any points $\mathbf{z}\in\Omega^{\delta}$ and $\mathbf{z}_1,\mathbf{w}_1\in\textnormal{int}\,{\Omega^{\delta}}$.
\hfill$\diamond$

\label{ex: Laplacian is null}
For any $\mathbf{u}\in{\mathbb Z}^2$, the field polynomials
\begin{align*}
    \phantom{\bigg\vert}
    \Delta_\sharp\boldsymbol\upxi(\mathbf{u})
    \,\coloneqq\,
    \sum_{\underset{\vert\mathbf{v}-\mathbf{u}\vert=1}{\mathbf{v}\in{\mathbb Z}^2}}
    \!\!\boldsymbol\upxi(\mathbf{v})
    -4\boldsymbol\upxi(\mathbf{u})
    \mspace{50mu}
    \textnormal{ and }
    \mspace{50mu}
    \Delta_\sharp\boldsymbol\uptheta(\mathbf{u})
    \,\coloneqq\,
    \sum_{\underset{\vert\mathbf{v}-\mathbf{u}\vert=1}{\mathbf{v}\in{\mathbb Z}^2}}
    \!\!\boldsymbol\uptheta(\mathbf{v})
    -4\boldsymbol\uptheta(\mathbf{u})
    \phantom{\bigg\vert}
\end{align*}
are null.
This can be straightforwardly verified from Remark~\ref{rmk: 2n pt function fDGFF}.
Moreover, using Wick's formula, one can see that, if $P\in\mathcal{P}$ is a field polynomial satisfying $\mathbf{u} \notin \textnormal{supp}\, P$, the field polynomials $\Delta_\sharp\boldsymbol\upxi(\mathbf{u})\cdot P$ and $\Delta_\sharp\boldsymbol\uptheta(\mathbf{u})\cdot P$ are null, too.
\hfill$\diamond$

By virtue of the factorisation of the Laplacian ---{Remark~\ref{rmk: factorisation laplacian}}--- and Example~\ref{ex: Laplacian is null}, we have that the field polynomials
\begin{align*}

    \mathrlap{\hspace{1pt}\overline{\scalebox{0.8}[1]{\phantom{\ensuremath{\partial}}}}}\ensuremath{\partial}
_\sharp\boldsymbol{\upchi}(\mathbf{u})\,,
	\mspace{50mu}

    \mathrlap{\hspace{1pt}\overline{\scalebox{0.8}[1]{\phantom{\ensuremath{\partial}}}}}\ensuremath{\partial}
_\sharp\boldsymbol{\upeta}(\mathbf{u})\,,
	\mspace{50mu}
	\partial_\sharp 
    \mathrlap{\hspace{-0.7pt}\overline{\scalebox{1.1}[1]{\phantom{\ensuremath{\boldsymbol{\upchi}}}}}}\ensuremath{\boldsymbol{\upchi}}
(\mathbf{u})\,,
	\mspace{40mu}
	\textnormal{and}
	\mspace{40mu}
	\partial_\sharp 
    \mathrlap{\hspace{-0.2pt}\overline{\scalebox{0.9}[1]{\phantom{\ensuremath{\boldsymbol{\upeta}}}}}}\ensuremath{\boldsymbol{\upeta}}
(\mathbf{u})
\end{align*}
are null for any $\mathbf{u}\in{\mathbb Z}^2$.
\hfill$\diamond$

\label{ex: cubic null field}
The field polynomial~$\Delta_\sharp\boldsymbol\upxi(\mathbf{u})\boldsymbol\uptheta(0)\boldsymbol\upxi(0) + 4\pi \delta_{0,\mathbf{u}}\boldsymbol\upxi(0)$ is null.
To see this, we evaluate it at some $\mathbf{z}$ in some discrete domain~$\Omega^{\delta}$ and test it against distant insertions.
Using Wick's formula and the multilinearity of correlation functions, we have
\begin{align*}
    \Big\langle 
    \Big( \Delta_\sharp &\,\xi(\mathbf{z} + \delta\mathbf{u}) \theta(\mathbf{z}) + 4\pi \delta_{0,\mathbf{u}} \Big) \, \xi(\mathbf{z})
    \cdot
    \xi(\mathbf{z}_1)\cdots\xi(\mathbf{z}_n)\,
    \theta(\mathbf{w}_1)\cdots\theta(\mathbf{z}_m)
     \Big\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}}
    \phantom{\bigg\vert}
    \\
    &
    \,=
    \bigg( \big(\Delta_\sharp\big)_{\mathbf{u}}
    \Big\langle 
    \xi(\mathbf{z}+\delta\mathbf{u}) \theta(\mathbf{z}) 
     \Big\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}}
    +
    4\pi \delta_{0,\mathbf{u}} \,\bigg)\,
    \Big\langle 
    \xi(\mathbf{z})
    \,
    \xi(\mathbf{z}_1)\cdots\xi(\mathbf{z}_n)\,
    \theta(\mathbf{w}_1)\cdots\theta(\mathbf{w}_m)
     \Big\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}}
    \\
    &
    \mspace{20mu}
    -\,
    \big(\Delta_\sharp\big)_{\mathbf{u}}
    \Big\langle 
    \xi(\mathbf{z}+\delta\mathbf{u}) \xi(\mathbf{z}) 
     \Big\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}}
    \,
    \Big\langle 
    \theta(\mathbf{z})
    \,
    \xi(\mathbf{z}_1)\cdots\xi(\mathbf{z}_n)\,
    \theta(\mathbf{w}_1)\cdots\theta(\mathbf{w}_m)
     \Big\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}}
    \phantom{\Bigg\vert}
    \\
    &
    \mspace{20mu}
    -\,
    \sum_i (-1)^{i}
    \big(\Delta_\sharp\big)_{\mathbf{u}}
    \Big\langle 
    \xi(\mathbf{z}+\delta\mathbf{u}) \xi(\mathbf{z}_i) 
     \Big\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}}
    \,
    \Big\langle 
    \xi(\mathbf{z}) \, \theta(\mathbf{z})
    \cdots \widehat{\xi(\mathbf{w}_i)} \cdots
     \Big\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}}
    \phantom{\Bigg\vert}
    \\
    &
    \mspace{20mu}
    -\,
    \sum_j (-1)^{n+j}
    \big(\Delta_\sharp\big)_{\mathbf{u}}
    \Big\langle 
    \xi(\mathbf{z}+\delta\mathbf{u}) \theta(\mathbf{w}_j) 
     \Big\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}}
    \,
    \Big\langle 
    \xi(\mathbf{z}) \, \theta(\mathbf{z})
    \cdots \widehat{\theta(\mathbf{w}_j)} \cdots
     \Big\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}}
    \phantom{\Bigg\vert}\,,
\end{align*}
where the hat ($\,\widehat{\phantom{m}}\;\!$) indicates that a term does not appear in the product.
Note that in the right-hand side of the above equation, the first factor in each term vanishes, proving the nullity of the given field polynomial.
\hfill$\diamond$

\label{ex: rep of ground states}
In Theorem~\ref{thm: isomorphism} below, we prove that the space of local fields~$\mathcal{F}$ is isomorphic to the logarithmic Fock space of the symplectic fermions.
Through that isomorphism the local fields
\begin{align*}
    \mspace{76mu}
    \mathbf{1} \,\coloneqq\, 1 + \textnormal{\small Null}
    \mspace{50mu}
    \textnormal{ and }
    \mspace{50mu}
    \boldsymbol{\upomega} \, \coloneqq - \boldsymbol\upxi(0)\boldsymbol\uptheta(0) + \textnormal{\small Null}
\end{align*}
correspond to the identity field and its logarithmic partner, respectively,
and the local fields
\begin{align*}
    \phantom{\Big\vert}
    \boldsymbol{\upxi} \,\coloneqq\, \boldsymbol\upxi(0) + \textnormal{\small Null}
    \mspace{50mu}
    \textnormal{ and }
    \mspace{50mu}
    \boldsymbol{\uptheta} \, \coloneqq  \boldsymbol\uptheta(0) + \textnormal{\small Null}
\end{align*}
correspond to the fermionic ground states.
\hfill$\diamond$

\label{prop: current modes}
Let $P+\textnormal{\small Null}\in\mathcal{F}$ be a local field.
The linear operators
\begin{align}
