	\mathbf{u}^{[k]}_\diamond\,
	\boldsymbol{\upeta}(\mathbf{u}_\textnormal{m}) \cdot P 
	+ \textnormal{\small Null}\,,
	\\
	\label{eq: chi bar mode}

    \mathrlap{\hspace{0pt}\overline{\scalebox{1}[1]{\phantom{\ensuremath{\boldsymbol{\chi}}}}}}\ensuremath{\boldsymbol{\chi}}
_{k}\big( P + \textnormal{\small Null}\big) &
