\text{ and }
\mspace{30mu}

    \mathrlap{\hspace{-1pt}\overline{\scalebox{0.85}[1]{\phantom{\ensuremath{\mathbf{L}}}}}}\ensuremath{\mathbf{L}}
_{n}
\coloneqq
\sum_{k \,\geq\, n/2}

    \mathrlap{\hspace{0pt}\overline{\scalebox{1}[1]{\phantom{\ensuremath{\boldsymbol{\chi}}}}}}\ensuremath{\boldsymbol{\chi}}
_{n-k} 
    \mathrlap{\hspace{0pt}\overline{\scalebox{1}[1]{\phantom{\ensuremath{\boldsymbol{\eta}}}}}}\ensuremath{\boldsymbol{\eta}}
_{k}
-
\sum_{k \,<\, n/2}

    \mathrlap{\hspace{0pt}\overline{\scalebox{1}[1]{\phantom{\ensuremath{\boldsymbol{\eta}}}}}}\ensuremath{\boldsymbol{\eta}}
_{k} 
    \mathrlap{\hspace{0pt}\overline{\scalebox{1}[1]{\phantom{\ensuremath{\boldsymbol{\chi}}}}}}\ensuremath{\boldsymbol{\chi}}
_{n-k}\,,
\end{align*}
for $n\in{\mathbb Z}$, are well-defined and constitute two commuting representations of the Virasoro algebra with central charge $c=-2$.

\label{thm: isomorphism}
As representations of the symplectic fermions algebra, we have the isomorphism
\begin{align*}
    \mathcal{F}
    \,\cong\,
    \mathscr{F}{\!\!\textnormal{\footnotesize\itshape ock}}\,.
\end{align*}

\label{thm: scaling limit}
Fix a positive constant $\lambda\in{\mathbb R}_{>0}$.
For $i=1,\ldots,n$, let $\boldsymbol{\varphi}_i\in\mathcal{F}$ be a local field with generalised scaling dimension $\Delta_i+\bar\Delta_i$.
Let $P_i^\delta\in\mathcal{P}$ be a field-polynomial representative of the local field
\begin{align*}
    \boldsymbol{\varphi}_i
    \,-\, \log \big( \lambda \, \delta \big)
    \Big[ ({\mathbf{L}}_{0}+ 
    \mathrlap{\hspace{-1pt}\overline{\scalebox{0.85}[1]{\phantom{\ensuremath{\mathbf{L}}}}}}\ensuremath{\mathbf{L}}
_{0})-(\Delta_i+\bar\Delta_i)\Big]
    \boldsymbol{\varphi}_i\,.
\end{align*}
We have
\begin{align*}
    \frac{\Big\langle P_1^\delta\big(\mathbf{z}_1^\delta\big)
    \cdots P_n^\delta\big(\mathbf{z}_n^\delta\big) \Big\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}}}
    {\mathlarger{\mathlarger{\delta}}^{\,\sum_i(\Delta_i+\bar\Delta_i)}}
    \mspace{20mu}
    \xrightarrow{\mspace{50mu}\delta\,\downarrow\,0\mspace{50mu}}
    \mspace{20mu}
    \Big\langle \boldsymbol{\varphi}_1(z_1) \cdots \boldsymbol{\varphi}_n(z_n) \Big\rangle_{\Omega; \alpha(\lambda)}^{\textnormal{SyFe}}
\end{align*}
uniformly for $(z_1,\ldots,z_n)$  on compacts of $\textnormal{Conf}_{n}( \Omega )$, where we used $P_i^\delta\big(\mathbf{z}_i^\delta\big)\coloneqq\textnormal{ev}_{\mathbf{z}_i^\delta}^{\Omega^{\delta}}\big(P_i^\delta\big)$ and $\alpha(\lambda)\coloneqq 2 \big( \log \lambda + \mathsf{C}\, \big)$.

The ground state~$\boldsymbol{\upomega}$ does not have a well-defined scaling dimension ---recall that we have $({\mathbf{L}}_{0}+ 
    \mathrlap{\hspace{-1pt}\overline{\scalebox{0.85}[1]{\phantom{\ensuremath{\mathbf{L}}}}}}\ensuremath{\mathbf{L}}
_{0})\boldsymbol{\upomega} = 2\cdot\mathbf{1}$--- which implies that it requires a logarithmic correction to get a non-trivial scaling limit.
More precisely, we have the convergence
\begin{align*}
    \Big\langle 
    \textnormal{ev}_{\mathbf{z}^\delta}^{\Omega^{\delta}}
    \Big(  \boldsymbol{\upomega}  - 2 \log( \lambda \, \delta ) \mathbf{1}
    \Big) 
     \Big\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}}
    \mspace{20mu}
    \xrightarrow{
    \mspace{50mu}\delta\,\downarrow\,0\mspace{50mu}
    }
    \mspace{20mu}
    \Big\langle \boldsymbol{\omega}(z) \Big\rangle_{\Omega; \alpha(\lambda)}^{\textnormal{SyFe}}
    = \, - \, 4\pi\,\mathbf{g}_{\Omega}(z,z) - \alpha(\lambda)
\end{align*}
uniformly for $z$ on compacts of $\Omega$.
The arbitrary CFT constant $\alpha$ on the right-hand side arises from the arbitrary linear scale $\lambda$ chosen in the discrete.
\hfill$\diamond$

