The relevant fDGFF correlation functions are then
\begin{align}
\label{eq: fDGFF corr fun}
    &
    \Big\langle 
    \textnormal{ev}_{\mathbf{z}_1^\delta}^{\Omega^{\delta}}\big( P_1 \big)
    \cdots
    \textnormal{ev}_{\mathbf{z}_n^\delta}^{\Omega^{\delta}}\big( P_n \big)
     \Big\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}}
    \, = \phantom{\Bigg\vert}
    \\ \nonumber
    &
    \mspace{20mu}
    =\,
    \prod_{i=1}^n
    \Bigg(
    \prod_{a=1}^{r_i}
    \sqint^{\sharp}_{\gamma^\eta_{i;a}(\delta)}
    \frac{\textnormal{d}^{\sharp} \mathbf{u}_{i;a}}{2\pi\mathbbm{i}} \,
    (\mathbf{u}_{i;a})_\diamond^{[-k_a^{(i)}]}
    \prod_{b=1}^{s_i}
    \;
    \sqint^{\sharp}_{\gamma^\chi_{i;b}(\delta)} \,
    \frac{\textnormal{d}^{\sharp} \mathbf{v}_{i;b}}{2\pi\mathbbm{i}}
    (\mathbf{v}_{i;b})_\diamond^{[-\ell_b^{(i)}]}
    \Bigg)
    \times
    \\ \nonumber
    &
    \mspace{30mu}
    \phantom{\Bigg\vert}
    \times
    \bigg\langle
    \partial^\bullet_\sharp\theta\big( \mathbf{z}_1^\delta + \delta (\mathbf{u}_{1;1})_\textnormal{m} \big)
    \cdots
    \partial^\bullet_\sharp\theta\big( \mathbf{z}_1^\delta + \delta (\mathbf{u}_{1;r_1})_\textnormal{m} \big)
    \,\cdot
    \\ \nonumber
    &
    \mspace{90mu}
    \cdot
    \partial^\bullet_\sharp\xi\big( \mathbf{z}_1^\delta + \delta (\mathbf{v}_{1;1})_\textnormal{m} \big)
    \cdots
    \partial^\bullet_\sharp\xi\big( \mathbf{z}_1^\delta + \delta (\mathbf{v}_{1;s_1})_\textnormal{m}\big)
    \Big(
    - \xi\big( \mathbf{z}_1^\delta \big) \theta\big( \mathbf{z}_1^\delta \big) 
    - 2\log\big(\lambda\delta\big)
    \Big)
    \cdots
    \\ \nonumber
    &
    \mspace{90mu}
    \cdots\;
    \partial^\bullet_\sharp\theta\big( \mathbf{z}_n^\delta + \delta (\mathbf{u}_{n;1})_\textnormal{m} \big)
    \cdots
    \partial^\bullet_\sharp\theta\big( \mathbf{z}_n^\delta + \delta (\mathbf{u}_{n;r_n})_\textnormal{m} \big)
    \cdot\phantom{\Bigg\vert}
    \\ \nonumber
    &
    \mspace{90mu}
    \cdot
    \partial^\bullet_\sharp\xi\big( \mathbf{z}_n^\delta + \delta (\mathbf{v}_{n;1})_\textnormal{m} \big)
    \cdots
    \partial^\bullet_\sharp\xi\big( \mathbf{z}_n^\delta + \delta (\mathbf{v}_{n;s_n})_\textnormal{m}\big)
    \Big(
    - \xi\big( \mathbf{z}_n^\delta \big) \theta\big( \mathbf{z}_n^\delta \big) 
    - 2\log\big(\lambda\delta\big)
    \Big)
    \bigg\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}}
    \!\!\!.
\end{align}
Let us focus on the integrand that is an fDGFF correlation function.
By the fDGFF generalised Wick's formula ---Remark~\ref{rmk: discrete Wick with log corrections}---, and by linearity of the fDGFF correlation functions, it can be rewritten as sums of products of factors of the two following types:
\begin{align*}
    \sqint^{\sharp}_{\gamma^\eta_{i;a}(\delta)}
    \!\!\!\!
    \frac{\textnormal{d}^{\sharp} \mathbf{u}_{i;a}}{2\pi\mathbbm{i}} \,
    (\mathbf{u}_{i;a})_\diamond^{[-k_a^{(i)}]}
    \sqint^{\sharp}_{\gamma^\chi_{j;b}(\delta)} \,
    \!\!\!\!
    \frac{\textnormal{d}^{\sharp} \mathbf{v}_{j;b}}{2\pi\mathbbm{i}}
    (\mathbf{v}_{i;b})_\diamond^{[-\ell_b^{(j)}]}
    \big(\partial^\bullet_\sharp\big)_{\!\mathbf{u}}
    \big(\partial^\bullet_\sharp\big)_{\!\mathbf{v}}
    \Big\langle 
    \theta ( \mathbf{z}_i^\delta+\delta(\mathbf{u}_{i;a})_\textnormal{m} )
    \xi ( \mathbf{z}_j^\delta+\delta(\mathbf{v}_{j;b})_\textnormal{m} )
     \Big\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}}
\end{align*}
and
\begin{align*}
    - \Big\langle 
    \xi \big( \mathbf{z}_i^\delta \big)
    \theta \big( \mathbf{z}_i^\delta \big)
     \Big\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}}
    - 2\log\big(\lambda\delta\big)\,.
\end{align*}
The latter type of factor, converges to 
\begin{align*}
    \Big\langle \boldsymbol{\omega}(x) \Big\rangle_{\Omega; \alpha(\lambda)}^{\textnormal{SyFe}}
\end{align*}
uniformly for $x$ on compacts of $\Omega$ by Corollary~\ref{coro: converg of partner}.
The former type, when renormalised by $\delta^{-(k_a^{(i)}+\ell_b^{(j)})}$, converges uniformly for $(z_i,z_j)$ on compacts of $\textnormal{Conf}_{2}( \Omega )$ to
\begin{align*}
    \oint_{\Gamma^\eta_{i;a}}
    \!\!
    \frac{\textnormal{d} \zeta^{\eta}_{i;a}}{2\pi\mathbbm{i}} \,
    \big( \zeta^{\eta}_{i;a} \big)^{-k_a^{(i)}}
    \sqint^{\sharp}_{\Gamma^\chi_{j;b}} \,
    \!\!
    \frac{\textnormal{d} \zeta^{\chi}_{j;b}}{2\pi\mathbbm{i}} \,
    \big( \zeta^{\chi}_{j;b} \big)^{-\ell_b^{(j)}}
    \partial_{\zeta^{\eta}_{i;a}}
    \partial_{\zeta^{\chi}_{j;b}}
    \Big\langle 
    \boldsymbol{\theta} \big( z_i+\zeta^{\eta}_{i;a} \big)\,
    \boldsymbol{\xi} \big( z_j+\zeta^{\chi}_{j;b} \big)
     \Big\rangle_{\Omega; \alpha(\lambda)}^{\textnormal{SyFe}}\,,
\end{align*}
where we took $\alpha = \alpha(\lambda)$ since the CFT correlation does not depend on this constant.
To see this, recall that for $\mathbf{u}^\delta\in\delta{\mathbb Z}^2_\diamond$ satisfying $\delta\mathbf{u}^\delta\to\zeta \in {\mathbb C}$ as $\delta\downarrow0$, we have ---Proposition~\ref{prop: monomials} (Property~8)--- the convergence of the discrete monomials
\begin{align*}
    \delta^k \big(\mathbf{u}^\delta\big)^{[k]}\;
    \xlongrightarrow{\;\;\; \delta\downarrow 0\;\;\;}
    \;\zeta^k
\end{align*}
uniformly for $\zeta$ on compacts of ${\mathbb C}\setminus\{0\}$.
We also need the classical result of the scaling-limit convergence of the double derivatives of the discrete (Dirichlet) Green's function to its continuum counterpart when renormalized by $\delta^2$---see \cite[Section~3.3]{ABK-DGFF_local_fields}.
Then, when each of the discrete differentials $\textnormal{d}^{\sharp}$ is renormalised by $\delta$, the expression $\eqref{eq: fDGFF corr fun}$ becomes a Riemann-sum approximation of double integrals.
Collecting the powers of $\delta$ we find that, if we renormalise~\eqref{eq: fDGFF corr fun} by
\begin{align*}
    {{\mathlarger{\delta}}^{\,-\sum_i\big( \sum_a k_{i;a} + \sum_b \ell_{i;b} \big)}},
\end{align*}
it converges uniformly on compacts to \eqref{eq: CFT corr fun} ---after a shift in the integration variables---.
Note that $\sum_a k_{i;a} + \sum_b \ell_{i;b}$ is the generalised scaling dimension of the field $\boldsymbol{\varphi}_i$.

Via the burning algorithm, recurrent configuration with dissipative sites at $\mathbf{W}$ are in bijection with spanning forests of $\Omega^{\delta}$ where $\partial\Omega^{\delta}$ and each of the dissipative sites $\mathbf{w}_i$ belongs in a different tree.
Equivalently, these configurations are in bijection with spanning trees of the graph obtained from $(V_{\Omega^{\delta}},E_{\Omega^{\delta}})$ by fusing all dissipative sites $\mathbf{w}_i$ with the boundary vertex $\partial\Omega^{\delta}$---let $\tilde{\mathcal{G}}$ denote this modified graph.
The Dirichlet Laplacian matrix $\tilde\Delta_{\Omega^{\delta}}^{\texttt{D}}$ of $\tilde{\mathcal{G}}$ is just $\tilde\Delta_{\Omega^{\delta}}^{\texttt{D}}$ with the rows and columns of the dissipative sites removed.

\noindent
Let us check that the Green's function of $\tilde{\mathcal{G}}$ is given by
\begin{align*}
    \tilde\mathbf{G} (\mathbf{x},\mathbf{y})
    \,=\,
    \frac{1}{4\pi}
    \frac{
    \big\langle 
    \xi(\mathbf{x})\theta(\mathbf{y})
    D(\mathbf{w}_1)\cdots D(\mathbf{w}_m)
     \big\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}}}
    {\big\langle 
    D(\mathbf{w}_1)\cdots D(\mathbf{w}_m)
     \big\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}}}\,,
\end{align*}
where, recall, that $D(\mathbf{w}_i) = \tfrac{1}{4\pi}\xi(\mathbf{w}_i)\theta(\mathbf{w}_i)$.
From Remark~\ref{rmk: 2n pt function fDGFF}, we see that it is symmetric, we have $\big\langle 
    \xi(\mathbf{x})\theta(\mathbf{y})
    D(\mathbf{w}_1)\cdots D(\mathbf{w}_m) \big\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}}
    \,=\, 0$
for $x=\mathbf{w}_i$, and
\begin{align*}
    \big\langle 
    \xi(\mathbf{x})\theta(\mathbf{y})
    D(\mathbf{w}_1)\cdots D(\mathbf{w}_m) \big\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}}
    \,=\, & \,
    \big\langle 
    \xi(\mathbf{x})\theta(\mathbf{y}) \big\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}}\,
    \big\langle 
    D(\mathbf{w}_1)\cdots D(\mathbf{w}_m) \big\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}}
    \phantom{\bigg\vert}
    \\
    & \mspace{70mu} \phantom{\Bigg\vert}
    + \;
    \parbox{150pt}{\centering discrete harmonic terms \linebreak w.r.t.~$\mathbf{x}$ at $\Omega^{\delta}\setminus \mathbf{W}$\,,}
\end{align*}
which straightforwardly leads to $\big[\tilde\Delta_{\Omega^{\delta}}^{\texttt{D}}\tilde\mathbf{G}\big](\mathbf{x},\mathbf{y})=-\delta_{\mathbf{x},\mathbf{y}}$ for $\mathbf{x},\mathbf{y}\in\Omega^{\delta}\setminus\mathbf{W}$.

























































































\noindent
At this point, similarly as in the case of the height-one field without the presence of dissipation fields, one can prove that we have
\begin{align*}
    {\mathbb E}^{\textnormal{ASM}}_{\Omega^{\delta}\setminus\mathbf{W}}
    \big[\,
    \mathsf{h}_1(\mathbf{w}_1)
    \cdots
    \mathsf{h}_1(\mathbf{w}_m)
    \big]
    \,=\,
    \Big\langle 
    H_1(\mathbf{z}_1) \cdots H_1(\mathbf{z}_m)
    D(\mathbf{w}_1) \cdots D(\mathbf{w}_n)
     \Big\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}}\,,
\end{align*}
where, recall, we defined $H_1(\mathbf{z}) \coloneqq \frac{1}{4\pi}\big[\prod_{e \sim \mathbf{z}}\big(\nabla_{\!\sharp}\xi(e)\nabla_{\!\sharp}\theta(e) - 1\big) - 1\big]$.

\noindent
To complete the proof, we just need to prove
\begin{align*}
    \Big\langle 
    D(\mathbf{w}_1) \cdots D(\mathbf{w}_n)
     \Big\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}}
    \,=\,
    \frac
    {\big\vert
    \mathcal{R}_{\Omega^{\delta}}
    \big\vert}
    {\big\vert
    \mathcal{R}_{\Omega^{\delta}\setminus\mathbf{W}}
    \big\vert}
    \,.
\end{align*}
Recall that recurrent configurations are in bijection with spanning trees via the burning algorithm.
Then, on the one hand, using the matrix-tree theorem, we get
\begin{align}
\label{eq: statmech1}
    \frac{\big\vert 
    \mathcal{R}_{\Omega^{\delta}\setminus\mathbf{W}}
    \big\vert}
    {\big\vert \mathcal{R}_{\Omega^{\delta}} \big\vert}
    \,=\, & \,
    \frac{\vert \det \tilde\Delta_{\Omega^{\delta}}^{\texttt{D}} \,\vert}
    {\vert \det \Delta_{\Omega^{\delta}}^{\texttt{D}} \,\vert}
    \\ \nonumber
    \,=\, & \,
    \frac{\big\vert \det \big( \, \Delta_{\Omega^{\delta}}^{\texttt{D}} - \sum\nolimits_i \mathbbm{1}^{\mathbf{w}_i} \big)\big\vert}
    {\vert \det \Delta_{\Omega^{\delta}}^{\texttt{D}} \,\vert}
    \phantom{\Bigg\vert}
\end{align}
\begin{align*}    
    \,=\, & \,
    \frac{
    \vert \det \Delta_{\Omega^{\delta}}^{\texttt{D}} \,\vert
    \cdot
    \big\vert
    \det \big( \, \mathbb{I} + \sum\nolimits_i \mathbf{G}_{\Omega^{\delta}} \mathbbm{1}^{\mathbf{w}_i} \big)
    \big\vert }
    {\vert \det \Delta_{\Omega^{\delta}}^{\texttt{D}} \,\vert}
    \\ \nonumber
    \,=\, & \,
    \Big\vert
    \det \Big( \, \mathbb{I} + \sum\nolimits_i \mathbf{G}_{\Omega^{\delta}} \mathbbm{1}^{\mathbf{w}_i} \Big)
    \Big\vert
    \\ \nonumber
    \,=\, & \,
    \big\vert
    \det\nolimits_{\mathbf{W}} ( \, \mathbb{I} + \mathbf{G}_{\Omega^{\delta}} )
    \,\big\vert\phantom{\Bigg\vert}
    \\ \nonumber
    \,=\, & \,
    \sum_{\sigma\in\mathfrak{S}_n}
    (-1)^\sigma
    \prod_{i=\sigma(i)}
    \Big(
    1 + \mathbf{G}_{\Omega^{\delta}} ( \mathbf{w}_i , \mathbf{w}_i )
    \Big)
    \prod_{j\neq\sigma(j)}
    \mathbf{G}_{\Omega^{\delta}} ( \mathbf{w}_j , \mathbf{w}_{\sigma(j)} )
\end{align*}
where $\det_{\mathbf{W}}$ denotes the determinant of the submatrix with rows and columns indexed by $\mathbf{W}=\{\mathbf{w}_1,\ldots,\mathbf{w}_n\}$\,.
On the other hand, from the fermionic Wick's formula, it is straightforward to get get
\begin{align*}
    \Big\langle 
    \xi(\mathbf{w}_1) \theta(\mathbf{w}_1)
    \cdots
    \xi(\mathbf{w}_n) \theta(\mathbf{w}_n)
     \Big\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}}
    = & \phantom{\bigg\vert}
    \Big\langle 
    \xi(\mathbf{w}_1) \theta(\mathbf{w}_1)
     \Big\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}}\!
    \Big\langle 
    \xi(\mathbf{w}_2) \theta(\mathbf{w}_2)
    \cdots
    \xi(\mathbf{w}_n) \theta(\mathbf{w}_n)
     \Big\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}}
    \\
    & \mspace{40mu} \phantom{\Bigg\vert} + \,
    \sum_{\underset{\sigma(1)\neq 1}{\sigma \in \mathcal{S}_n}}
    (-1)^{\sigma}
    \prod_{i=1}^{n}
    \Big\langle 
    \xi(\mathbf{w}_i) \theta(\mathbf{w}_{\sigma(i)}
     \Big\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}}\!\!\!,
\end{align*}
from which one can compute
\begin{align}
\label{eq: statmech2}
    \Big\langle 
    D(\mathbf{w}_1) \cdots D(\mathbf{w}_n)
     \Big\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}}
    \,=\, & \;
    \sum_{\sigma\in\mathfrak{S}_n}
    (-1)^\sigma
    \prod_{i=\sigma(i)}
    \bigg(
    1 +  \frac{1}{4\pi}\Big\langle 
    \xi(\mathbf{w}_i) \theta(\mathbf{w}_i)
     \Big\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}}\,
    \bigg)\,
    \times
    \\ \nonumber
    & \mspace{220mu}
    \phantom{\Bigg\vert}
    \times
    \prod_{j\neq\sigma(j)}
    \frac{1}{4\pi}
    \Big\langle 
    \xi(\mathbf{w}_j) \theta(\mathbf{w}_{\sigma(j)})
     \Big\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}}
    \!\!\!.
\end{align}
The complete the proof we just need to compare~\eqref{eq: statmech1} and \eqref{eq: statmech2} since we have the $2$-point function $\big\langle 
    \xi(\mathbf{z}) \theta(\mathbf{w})
     \big\rangle_{\Omega^{\delta}}^{\textnormal{fDGFF}} = 4\pi \, \mathbf{G}_{\Omega^{\delta}} (\mathbf{z},\mathbf{w})$.
